#!/usr/bin/env node
// render-table.mjs
//
// Marker contract:
//   This script edits README.md in place. It locates the block bounded by
//   `<!-- BENCH START -->` and `<!-- BENCH END -->` and replaces the content
//   between those two lines with an autogenerated benchmark table sourced
//   from `bench/results/*.json`. The marker lines themselves are preserved.
//
//   Files outside that block are never touched. If the markers are missing,
//   the script exits with code 1 so CI catches the drift instead of silently
//   producing the wrong README.
//
// Result file naming:
//   bench/results/<device-slug>-<YYYYMMDDTHHMMSSZ>.json
//   The timestamp suffix is parsed from the filename so we can pick the
//   newest run per device without trusting clock fields inside the JSON.
//
// Result row schema (canonical BenchResult shape from src/dev/benchHarness.ts):
//   {
//     "device":      "Pixel 8 Pro",
//     "mode":        "real" | "demo",
//     "model":       "Gemma 4 E2B Q3_K_S" | "n/a",
//     "runs":        [{loadMs, firstTokenMs, tokensPerSec, totalMs, tokenCount}, ...],
//     "summary":     {
//       "p50FirstTokenMs":  number | null,
//       "p95FirstTokenMs":  number | null,
//       "p50TokensPerSec":  number | null,
//       "p95TokensPerSec":  number | null
//     },
//     "notes":       string (optional)
//   }
//
// Legacy snake_case keys (`first_token_ms_p50`, `tokens_per_sec_p50`,
// `cold_load_ms`) are still accepted for back-compat with hand-rolled
// fixtures.
//
// CLI:
//   node bench/render-table.mjs            # run against repo root
//   node bench/render-table.mjs --root DIR # run against a fixture dir (tests)
//
// Idempotency:
//   Running the script twice in a row produces zero diff. The trailing
//   newline of README.md is preserved byte-for-byte.

import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const MARKER_START = '<!-- BENCH START -->';
const MARKER_END = '<!-- BENCH END -->';
const PLACEHOLDER_TEXT = 'No benchmark data yet, run bench/run-node.sh to populate.';

const TIMESTAMP_RE = /-(\d{8}T\d{6}Z)\.json$/;

function parseArgs(argv) {
  const args = {root: null};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--root') {
      args.root = argv[i + 1];
      i++;
    }
  }
  return args;
}

function defaultRoot() {
  // bench/render-table.mjs lives at <repo>/bench/render-table.mjs
  const here = path.dirname(fileURLToPath(import.meta.url));
  return path.resolve(here, '..');
}

function readResults(resultsDir) {
  if (!fs.existsSync(resultsDir)) {
    return [];
  }
  const entries = fs.readdirSync(resultsDir).filter(name => name.endsWith('.json'));
  const rows = [];
  for (const name of entries) {
    const m = name.match(TIMESTAMP_RE);
    if (!m) {
      // Files without a timestamp suffix are ignored. This keeps the harness
      // forgiving when an operator drops a sample file alongside real runs.
      continue;
    }
    const stamp = m[1];
    const fullPath = path.join(resultsDir, name);
    let parsed;
    try {
      parsed = JSON.parse(fs.readFileSync(fullPath, 'utf8'));
    } catch (err) {
      throw new Error(`Failed to parse ${fullPath}: ${err.message}`);
    }
    rows.push({stamp, name, data: parsed});
  }
  return rows;
}

function latestPerDevice(rows) {
  // Sort by stamp descending so the first occurrence per device is the newest.
  const sorted = [...rows].sort((a, b) => (a.stamp < b.stamp ? 1 : -1));
  const seen = new Map();
  for (const row of sorted) {
    const key = String(row.data.device || row.name);
    if (!seen.has(key)) {
      seen.set(key, row);
    }
  }
  return [...seen.values()];
}

function formatCell(value, fallback = 'n/a') {
  if (value === null || value === undefined || value === '') {
    return fallback;
  }
  if (typeof value === 'number') {
    // Round latencies to 1 decimal for readability; cold-load milliseconds
    // are typically large enough that rounding does not lose signal.
    return Number.isInteger(value) ? String(value) : value.toFixed(1);
  }
  return String(value);
}

// Read either canonical BenchResult (camelCase + summary block) or the
// legacy snake_case fixture shape that earlier hand-written results used.
function firstTokenP50(row) {
  return row.summary?.p50FirstTokenMs ?? row.first_token_ms_p50 ?? null;
}

function tokensPerSecP50(row) {
  return row.summary?.p50TokensPerSec ?? row.tokens_per_sec_p50 ?? null;
}

function coldLoadMs(row) {
  if (typeof row.cold_load_ms === 'number') return row.cold_load_ms;
  // Cold load = the loadMs from the first run that recorded one.
  const firstNonNull = (row.runs ?? []).find(r => typeof r?.loadMs === 'number' && r.loadMs > 0);
  return firstNonNull ? firstNonNull.loadMs : null;
}

function tokensPerSecCell(row) {
  if (row.mode === 'demo') {
    return 'n/a (demo)';
  }
  return formatCell(tokensPerSecP50(row));
}

function modelCell(row) {
  if (row.mode === 'demo') {
    return formatCell(row.model, 'n/a');
  }
  return formatCell(row.model);
}

function buildTable(results) {
  const header =
    '| Device | Mode | Model | First-token (p50 ms) | Tokens/sec (p50) | Cold load (ms) | Notes |';
  const sep = '| --- | --- | --- | --- | --- | --- | --- |';

  if (results.length === 0) {
    const placeholder = `| ${PLACEHOLDER_TEXT} |  |  |  |  |  |  |`;
    return [header, sep, placeholder].join('\n');
  }

  const flat = results.map(r => r.data);
  const real = flat
    .filter(r => r.mode !== 'demo')
    .sort((a, b) => String(a.device).localeCompare(String(b.device)));
  const demo = flat
    .filter(r => r.mode === 'demo')
    .sort((a, b) => String(a.device).localeCompare(String(b.device)));

  const rows = [...real, ...demo].map(r => {
    return `| ${formatCell(r.device)} | ${formatCell(r.mode)} | ${modelCell(r)} | ${formatCell(
      firstTokenP50(r),
    )} | ${tokensPerSecCell(r)} | ${formatCell(coldLoadMs(r))} | ${formatCell(r.notes, '')} |`;
  });

  return [header, sep, ...rows].join('\n');
}

function replaceMarkers(readme, table) {
  const startIdx = readme.indexOf(MARKER_START);
  const endIdx = readme.indexOf(MARKER_END);
  if (startIdx === -1 || endIdx === -1 || endIdx < startIdx) {
    throw new Error(
      `Could not find ${MARKER_START} ... ${MARKER_END} block in README.md. ` +
        `Add the markers to the Benchmarks section before running this script.`,
    );
  }
  // Find the end-of-line for MARKER_START so we replace only the content
  // between the two marker lines.
  const afterStart = readme.indexOf('\n', startIdx);
  if (afterStart === -1) {
    throw new Error('README.md ends inside the BENCH START line.');
  }
  const beforeEnd = readme.lastIndexOf('\n', endIdx);
  if (beforeEnd === -1 || beforeEnd <= afterStart) {
    throw new Error('README.md BENCH markers are malformed.');
  }
  const prefix = readme.slice(0, afterStart + 1);
  const suffix = readme.slice(beforeEnd + 1);
  return `${prefix}${table}\n${suffix}`;
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const root = args.root ? path.resolve(args.root) : defaultRoot();
  const resultsDir = path.join(root, 'bench', 'results');
  const readmePath = path.join(root, 'README.md');

  if (!fs.existsSync(readmePath)) {
    console.error(`README.md not found at ${readmePath}`);
    process.exit(1);
  }

  const allRows = readResults(resultsDir);
  const latest = latestPerDevice(allRows);
  const table = buildTable(latest);

  const readme = fs.readFileSync(readmePath, 'utf8');
  let next;
  try {
    next = replaceMarkers(readme, table);
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }

  if (next !== readme) {
    fs.writeFileSync(readmePath, next);
    console.log(`Updated ${readmePath} with ${latest.length} device row(s).`);
  } else {
    console.log(`README.md already current (${latest.length} device row(s)).`);
  }
}

main();
